import cv2, numpy as np
from PIL import Image
im=cv2.imread('first_frame.png'); rgb=im[:,:,::-1]; g=cv2.cvtColor(im,cv2.COLOR_BGR2GRAY)
print('mean rows');
for y in range(0,144,4): print(y, round(g[y].mean(),1), round(g[y].min()), round(g[y].max()), 'dark',int((g[y]<20).sum()),'bright',int((g[y]>140).sum()))
print('mean cols')
for x in range(0,256,8): print(x,round(g[:,x].mean(),1),round(g[:,x].min()),round(g[:,x].max()),'dark',int((g[:,x]<20).sum()),'bright',int((g[:,x]>140).sum()))
# connected regions thresholds
for th,inv in [(20,1),(30,1),(45,1),(130,0),(150,0),(170,0)]:
 m=(g<th if inv else g>th).astype('uint8')
 n,lab,st,cen=cv2.connectedComponentsWithStats(m)
 print('\\nth',('<' if inv else '>'),th)
 for j in np.argsort(st[1:,4])[-12:][::-1]+1:
  if st[j,4]>10: print('area,bbox,cen',st[j,4],st[j,:4],np.round(cen[j],1))
# edge strong bbox contours
ed=cv2.Canny(g,60,120)
n,lab,st,cen=cv2.connectedComponentsWithStats(ed)
print('edges',ed.sum()/255)
for j in np.argsort(st[1:,4])[-20:][::-1]+1: print(st[j,4],st[j,:4],np.round(cen[j],1))
